INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (2, 1000101, "vo_minigame_1004_top_1_000", 10001, "vo_minigame_1004", 1, "ふっふっふ、これでカヤぴぃとボスを見返してやるです！");
