INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (1, 1000301, "vo_minigame_1004_top_1_004", 10003, "vo_minigame_1004", 2, "どんなケンカも売られた以上は買うのが喧嘩屋だ！やってやるぜ！");
